import static org.junit.Assert.*;

public class MutableDateTime_addWeeks_TriageGen0Test {

    @Test
    public void testAddWeeks_PositiveValue() {
        // Arrange: Set a specific date (2023-01-01 is a Sunday)
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 10, 0, 0, 0);
        int weeksToAdd = 2;

        // Act
        dt.addWeeks(weeksToAdd);

        // Assert: 2023-01-01 + 2 weeks = 2023-01-15
        assertEquals(2023, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(15, dt.getDayOfMonth());
        assertEquals(10, dt.getHourOfDay());
    }

    @Test
    public void testAddWeeks_ZeroValue() {
        // Arrange: Set a specific date
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 10, 0, 0, 0);
        int weeksToAdd = 0;

        // Act
        dt.addWeeks(weeksToAdd);

        // Assert: Date should remain unchanged because if (weeks > 0) condition is false
        assertEquals(2023, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(1, dt.getDayOfMonth());
    }

    @Test
    public void testAddWeeks_NegativeValue() {
        // Arrange: Set a specific date
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 10, 0, 0, 0);
        int weeksToAdd = -5;

        // Act
        dt.addWeeks(weeksToAdd);

        // Assert: Date should remain unchanged because if (weeks > 0) condition is false
        assertEquals(2023, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(1, dt.getDayOfMonth());
    }

    @Test
    public void testAddWeeks_LargeValueCrossingYearBoundary() {
        // Arrange: Set a date near the end of the year
        MutableDateTime dt = new MutableDateTime(2023, 12, 25, 10, 0, 0, 0);
        int weeksToAdd = 3; // 21 days

        // Act
        dt.addWeeks(weeksToAdd);

        // Assert: 2023-12-25 + 21 days = 2024-01-15
        assertEquals(2024, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(15, dt.getDayOfMonth());
    }
}
